// === META WEBHOOK VERIFICATION (GET) ===
const query = $input.first().json.query || {};
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];

const VERIFY_TOKEN = 'UsYwpKZhOv9oVVd8TXXFM5d-GTMZ6LfMvINBdn734AE';

if (mode === 'subscribe' && token === VERIFY_TOKEN) {
  console.log('[ARKOS] Meta verification OK');
  return [{ json: { challenge: challenge, verified: true } }];
} else {
  console.log('[ARKOS] Meta verification FAILED: bad token');
  return [{ json: { verified: false } }];
}

// === PARSE + VALIDATE WHATSAPP CLOUD API PAYLOAD ===
try {
  const body = $input.first().json.body;

  if (!body || !body.entry || !body.entry[0]) {
    console.log('[ARKOS] Skip: no entry in payload');
    return [{ json: { skip: true, reason: 'no_entry' } }];
  }

  const changes = body.entry[0].changes;
  if (!changes || !changes[0] || !changes[0].value) {
    console.log('[ARKOS] Skip: no changes');
    return [{ json: { skip: true, reason: 'no_changes' } }];
  }

  const value = changes[0].value;

  // Solo procesar mensajes, no status updates
  if (!value.messages || value.messages.length === 0) {
    console.log('[ARKOS] Skip: status update only');
    return [{ json: { skip: true, reason: 'status_update_only' } }];
  }

  const msg = value.messages[0];
  const contact = value.contacts ? value.contacts[0] : {};

  // === VALIDAR NUMERO AUTORIZADO ===
  const authorizedPhone = ($env.AUTHORIZED_OWNER_PHONE || '').toString().replace(/\D/g, '');
  const fromClean = msg.from.replace(/\D/g, '');

  if (authorizedPhone && !fromClean.includes(authorizedPhone)) {
    console.log('[ARKOS] BLOCKED: numero no autorizado:', msg.from);
    return [{ json: { skip: true, reason: 'unauthorized_number', from: msg.from } }];
  }

  console.log('[ARKOS] Mensaje recibido de', msg.from, '- tipo:', msg.type);

  // === NORMALIZAR INPUT ===
  let normalizedInput = '';
  switch(msg.type) {
    case 'text': normalizedInput = msg.text.body; break;
    case 'audio': normalizedInput = '[AUDIO_PENDIENTE_TRANSCRIPCION]'; break;
    case 'image': normalizedInput = msg.image.caption || '[IMAGEN_RECIBIDA]'; break;
    case 'document': normalizedInput = msg.document.caption || '[DOCUMENTO_RECIBIDO]'; break;
    default: normalizedInput = '[TIPO_NO_SOPORTADO: ' + msg.type + ']';
  }

  return [{ json: {
    skip: false,
    message_id: msg.id,
    from: msg.from,
    timestamp: msg.timestamp,
    type: msg.type,
    contact_name: contact.profile ? contact.profile.name : 'Jona',
    text: msg.type === 'text' ? msg.text.body : null,
    audio_id: msg.type === 'audio' ? msg.audio.id : null,
    image_id: msg.type === 'image' ? msg.image.id : null,
    document_id: msg.type === 'document' ? msg.document.id : null,
    caption: msg.image ? msg.image.caption : (msg.document ? msg.document.caption : null),
    phone_number_id: value.metadata.phone_number_id,
    display_phone: value.metadata.display_phone_number,
    normalized_input: normalizedInput
  }}];
} catch(err) {
  console.error('[ARKOS] Error parseando payload:', err.message);
  return [{ json: { skip: true, reason: 'parse_error', error: err.message } }];
}

// Preparar respuesta — con fallback si CEO Agent falla
let agentResponse;
try {
  agentResponse = $input.first().json;
} catch(e) {
  agentResponse = {};
}

const originalMsg = $node['Parse & Validate'].json;
const responseText = agentResponse.response || agentResponse.confirmation_message || 'Perdon Jona, tuve un problema procesando tu mensaje. Reintenta en un momento.';

console.log('[ARKOS] Respuesta para', originalMsg.from, ':', responseText.substring(0, 80) + '...');

return [{ json: {
  response_text: responseText,
  response_type: agentResponse.response_type || 'text',
  from: originalMsg.from,
  phone_number_id: originalMsg.phone_number_id,
  display_phone: originalMsg.display_phone
}}];
